python3 -c 'from pathlib import Path; import re; files=["Concept_Content_Distribution_Agency_Deep_Dive.md","Concept_Agency_Workflow_System.md","Concept_3_Email_Followup_Sequence.md","Concept_Accumulated_Trust_System.md","Concept_11_Lego_Bricks_Video_Framework__11_Lego_Bricks.md"]; base=Path("/sdcard/Nexus_Brain/Nexus_Brain/wiki/concepts");
for f in files:
 s=(base/f).read_text().splitlines(); print(f,"lines",len(s),"headings",sum(bool(re.match(r"^#{1,4} ",x)) for x in s),"wikilinks",sum(x.count("[[") for x in s),"frontmatter", next((i for i,x in enumerate(s) if x.strip()=="---" and i>0),None))'

